<?php
namespace App\Console\Commands\Sla; use App\Enums\TenantStatus; use App\Models\Tenant; use App\Services\Sla\EscalationService; use App\Services\Sla\SlaService; use Illuminate\Console\Command; use Throwable;
class EvaluateSlaCommand extends Command {protected $signature='sla:evaluate {--tenant=*}';protected $description='Evaluate SLA deadlines and execute deterministic escalations';public function handle(SlaService $sla,EscalationService $escalations):int{$changed=$executed=0;$tenants=Tenant::where('status',TenantStatus::Active)->when($this->option('tenant'),fn($q,$ids)=>$q->whereIn('id',$ids))->get();foreach($tenants as $tenant){try{tenancy()->initialize($tenant);$changed+=$sla->evaluate();$executed+=$escalations->evaluate();}catch(Throwable $e){$this->error("{$tenant->id}: {$e->getMessage()}");}finally{if(tenancy()->initialized)tenancy()->end();}}$this->info("Updated {$changed} SLA clock(s); executed {$executed} escalation(s).");return self::SUCCESS;}}
